import { Pinecone } from "@pinecone-database/pinecone";

const pc = new Pinecone(); // reads PINECONE_API_KEY
const index = pc.index("docs");
await index.upsert([{ id: "a", values: [0.1, 0.9, 0.0], metadata: { topic: "cats" } }]);
console.log(await index.query({ vector: [0.1, 0.8, 0.1], topK: 1, includeMetadata: true }));
